let woodAmount = 32;

// Collecting wood and giving it to the player
await skills.collectBlock(bot, 'oak_log', woodAmount);
const player = bot.nearestEntity(entity => entity.type === 'player');
if (player) {
    await skills.giveItem(bot, player.username, 'oak_log', woodAmount);
    log(bot, `Gave ${woodAmount} oak logs to ${player.username}`);
} else {
    log(bot, 'I collected ${woodAmount} logs and brought them back to you!.');
}

const baseSize = 15;
const height = 8;
const pos = bot.entity.position;

for (let y = 0; y < height; y++) {
    const layerSize = baseSize - 2 * y;
    const offset = Math.floor((baseSize - layerSize) / 2);
    for (let x = 0; x < layerSize; x++) {
        for (let z = 0; z < layerSize; z++) {
            await skills.placeBlock(bot, 'sandstone', pos.x + x + offset, pos.y + y, pos.z + z + offset);
            if(bot.interrupt_code) {log(bot, 'Code interrupted.');return;}
        }
    }
}

log(bot, 'Large, centered pyramid built successfully.');

let pos = world.getPosition(bot);

// Build the base with cobblestone
for (let x = -5; x <= 5; x++) {
    for (let z = -5; z <= 5; z++) {
        await skills.placeBlock(bot, 'cobblestone', pos.x + x, pos.y, pos.z + z);
    }
}

// Build the walls with stone bricks
for (let y = 1; y <= 5; y++) {
    for (let x = -5; x <= 5; x++) {
        await skills.placeBlock(bot, 'stone_bricks', pos.x + x, pos.y + y, pos.z - 5);
        await skills.placeBlock(bot, 'stone_bricks', pos.x + x, pos.y + y, pos.z + 5);
    }

    for (let z = -4; z <= 4; z++) {
        await skills.placeBlock(bot, 'stone_bricks', pos.x - 5, pos.y + y, pos.z + z);
        await skills.placeBlock(bot, 'stone_bricks', pos.x + 5, pos.y + y, pos.z + z);
