    await skills.placeBlock(bot, 'oak_log', pos.x + 5, pos.y + y, pos.z + 5);
}

// Add stone brick walls on top of the walls for detail
for (let x = -5; x <= 5; x++) {
    await skills.placeBlock(bot, 'stone_brick_wall', pos.x + x, pos.y + 6, pos.z - 5);
    await skills.placeBlock(bot, 'stone_brick_wall', pos.x + x, pos.y + 6, pos.z + 5);
}

for (let z = -4; z <= 4; z++) {
    await skills.placeBlock(bot, 'stone_brick_wall', pos.x - 5, pos.y + 6, pos.z + z);
    await skills.placeBlock(bot, 'stone_brick_wall', pos.x + 5, pos.y + 6, pos.z + z);
}

let botPosition = world.getPosition(bot);

/**
 * Function to build a circular tower
 * @param {number} baseX - The x coordinate of the tower base center
 * @param {number} baseY - The y coordinate of the tower base
 * @param {number} baseZ - The z coordinate of the tower base center
 * @param {number} radius - The radius of the tower
 * @param {number} height - The height of the tower
 */
async function buildCircularTower(baseX, baseY, baseZ, radius, height) {
    for (let y = 0; y < height; y++) {
        for (let x = -radius; x <= radius; x++) {
            for (let z = -radius; z <= radius; z++) {
                if (x*x + z*z <= radius*radius) {
                    await skills.placeBlock(bot, 'stone_bricks', baseX + x, baseY + y, baseZ + z);
                }
            }
        }
    }
}

/**
 * Function to build castle gate entrance
 * @param {number} x - The x coordinate of the entrance center
 * @param {number} y - The y coordinate of the entrance base
 * @param {number} z - The z coordinate of the entrance center
 */
async function buildCastleGate(x, y, z) {
    for (let i = 0; i < 5; i++) {
        await skills.placeBlock(bot, 'stone_bricks', x - 2, y + i, z);
        await skills.placeBlock(bot, 'stone_bricks', x + 2, y + i, z);
    }
    for (let i = -1; i <= 1; i++) {
        await skills.placeBlock(bot, 'oak_door', x + i, y, z);
    }
}

// Main function to build the castle
(async () => {
    let baseX = botPosition.x;
    let baseY = botPosition.y;
    let baseZ = botPosition.z;

    // Build four circular towers at the corners of the castle
    await buildCircularTower(baseX + 10, baseY, baseZ + 10, 4, 10);
    await buildCircularTower(baseX + 10, baseY, baseZ - 10, 4, 10);
    await buildCircularTower(baseX - 10, baseY, baseZ + 10, 4, 10);
    await buildCircularTower(baseX - 10, baseY, baseZ - 10, 4, 10);

    // Build the castle gate entrance
    await buildCastleGate(baseX, baseY, baseZ - 15);

    // Connect towers with walls (simple straight walls for now)
    for (let x = baseX - 9; x <= baseX + 9; x++) {
        await skills.placeBlock(bot, 'stone_bricks', x, baseY, baseZ + 9);
        await skills.placeBlock(bot, 'stone_bricks', x, baseY, baseZ - 9);
    }
    for (let z = baseZ - 9; z <= baseZ + 9; z++) {
        await skills.placeBlock(bot, 'stone_bricks', baseX + 9, baseY, z);
        await skills.placeBlock(bot, 'stone_bricks', baseX - 9, baseY, z);
    }
})();

let position = world.getPosition(bot);
let castleX = position.x + 5;
let castleY = position.y;
let castleZ = position.z + 5;
let radius = 5;
let height = 10;

async function buildCircle(centerX, centerY, centerZ, radius, blockType) {
    for(let y = 0; y < height; y++) {
        for (let angle = 0; angle < 360; angle += 10) {
            let rad = angle * (Math.PI / 180);
            let x = centerX + Math.round(radius * Math.cos(rad));
            let z = centerZ + Math.round(radius * Math.sin(rad));
            await skills.placeBlock(bot, blockType, x, centerY + y, z);
        }
    }
}

async function buildEmbrasures(centerX, centerY, centerZ, radius, blockType) {
    for(let y = 1; y <= height; y += 2) {
        for (let angle = 0; 360; angle += 20) {
            let rad = angle * (Math.PI / 180);
            let x = centerX + Math.round((radius - 1) * Math.cos(rad));
            let z = centerZ + Math.round((radius - 1) * sin(rad));
            await skills.breakBlockAt(bot, x, centerY + y, z);
        }
    }
}

async function buildCastle() {
    let tower1X = castleX + radius;
    let tower1Z = castleZ + radius;
    let tower2X = castleX + radius;
    let tower2Z = castleZ - radius;
    let tower3X = castleX - radius;
    let tower3Z = castleZ + radius;
    let tower4X = castleX - radius;
    let tower4Z = castleZ - radius;

    await buildCircle(tower1X, castleY, tower1Z, radius, "stone_bricks");
    await buildCircle(tower2X, castleY, tower2Z, radius, "stone_bricks");
    await buildCircle(tower3X, castleY, tower3Z, radius, "stone_bricks");
    await buildCircle(tower4X, castleY, tower4Z, radius, "stone_bricks");

    await buildEmbrasures(tower1X, castleY, tower1Z, radius, "glass");
    await buildEmbrasures(tower2X, castleY, tower2Z, radius, "glass");
    await buildEmbrasures(tower3X, castleY, tower3Z, radius, "glass");
    await buildEmbrasures(tower4X, castleY, tower4Z, radius, "glass");
}

await buildCastle();

