} else {
    log(bot,"No water found nearby.");
}

// First, let me find and collect some coal
let coalBlock = world.getNearestBlock(bot, 'coal_ore', 64);
if (coalBlock) {
    await skills.collectBlock(bot, 'coal_ore', 1);
}

// Now, let's return to the surface
let surfacePosition = { x: 1158, y: 64, z: -425 };
await skills.goToPosition(bot, surfacePosition.x, surfacePosition.y, surfacePosition.z);

// Next, crafting a furnace at the crafting table
await skills.craftRecipe(bot, "crafting_table");
await skills.craftRecipe(bot, "furnace");

// Finally, let's smelt the raw iron in our inventory
await skills.smeltItem(bot, "raw_iron", 8);

const position = world.getPosition(bot);

const startX = Math.floor(position.x);
const startY = Math.floor(position.y);
const startZ = Math.floor(position.z);

const width = 7;
const depth = 7;
const height = 4;

// Build the stone foundation
for (let x = startX; x < startX + width; x++) {
    for (let z = startZ; z < startZ + depth; z++) {
        await skills.placeBlock(bot, 'stone', x, startY - 1, z);
    }
}

// Build the corner logs
for (let y = startY; y < startY + height; y++) {
    await skills.placeBlock(bot, 'oak_log', startX, y, startZ);
    await skills.placeBlock(bot, 'oak_log', startX + width - 1, y, startZ);
    await skills.placeBlock(bot, 'oak_log', startX, y, startZ + depth - 1);
    await skills.placeBlock(bot, 'oak_log', startX + width - 1, y, startZ + depth - 1);
}

// Build the wooden walls
for (let x = startX; x < startX + width; x++) {
    for (let y = startY; y < startY + height; y++) {
        for (let z = startZ; z < startZ + depth; z++) {
            if (
                (x === startX || x === startX + width - 1 || z === startZ || z === startZ + depth - 1) &&
                !(x === startX && z === startZ) &&
                !(x === startX + width - 1 && z === startZ) &&
                !(x === startX && z === startZ + depth - 1) &&
                !(x === startX + width - 1 && z === startZ + depth - 1)
            ) {
                await skills.placeBlock(bot, 'oak_planks', x, y, z);
            }
        }
    }
}

// Create space for windows (1 block gap at each side of center)
for (let y = startY + 2; y <= startY + 3; y++) {
    await skills.breakBlockAt(bot, startX + Math.floor(width / 2), y, startZ);
    await skills.breakBlockAt(bot, startX, y, startZ + Math.floor(depth / 2));
}

// Create space for door
await skills.breakBlockAt(bot, startX + Math.floor(width / 2), startY, startZ);
await skills.breakBlockAt(bot, startX + Math.floor(width / 2), startY + 1, startZ);

// Place door
await skills.placeBlock(bot, 'oak_door', startX + Math.floor(width / 2), startY, startZ);

// Place windows
await skills.placeBlock(bot, 'glass', startX + Math.floor(width / 2), startY + 2, startZ);
await skills.placeBlock(bot, 'glass', startX, startY + 2, startZ + Math.floor(depth / 2));
await skills.placeBlock(bot, 'glass', startX + Math.floor(width / 2), startY + 3, startZ);
await skills.placeBlock(bot, 'glass', startX, startY + 3, startZ + Math.floor(depth / 2));

// Build the roof
for (let x = startX; x < startX + width; x++) {
    for (let z = startZ; z < startZ + depth; z++) {
        await skills.placeBlock(bot, 'oak_stairs', x, startY + height, z, 'top');
    }
}

const digRoom = async () => {
  let pos = world.getPosition(bot);

  // Dig down 6 blocks
  for (let i = 0; i < 6; i++) {
    await skills.breakBlockAt(bot, pos.x, pos.y - i, pos.z);
  }

  pos = world.getPosition(bot);
  const startX = pos.x;
  const startY = pos.y - 6;
  const startZ = pos.z;

  // Clear a 6x8 room 3 blocks tall
  for (let y = startY; y < startY + 3; y++) {
    for (let x = startX; x < startX + 6; x++) {
      for (let z = startZ; z < startZ + 8; z++) {
        await skills.breakBlockAt(bot, x, y, z);
      }
    }
  }
};

const buildBase = async () => {
  await digRoom();

  let pos = world.getPosition(bot);
  const startX = pos.x;
  const startY = pos.y - 6;
  const startZ = pos.z;

  // Build walls and floor with cobblestone
  for (let y = startY; y < startY + 3; y++) {
    for (let x = startX; x < startX + 6; x++) {
      for (let z = startZ; z < startZ + 8; z++) {
        if (x === startX || x === startX + 5 || z === startZ || z === startZ + 7 || y === startY) {
          await skills.placeBlock(bot, "cobblestone", x, y, z);
        }
      }
    }
  }

  // Add roof with oak planks
  for (let x = startX; x < startX + 6; x++) {
    for (let z = startZ; z < startZ + 8; z++) {
      await skills.placeBlock(bot, "oak_planks", x, startY + 3, z);
    }
  }
};

buildBase();

