}

// Build the cone shaped roof
for (let y = 0; y < radius; y++) {
  let r = radius - y;
  for (let x = startX - r; x <= startX + r; x++) {
    for (let z = startZ - r; z <= startZ + r; z++) {
      if ((x - startX) ** 2 + (z - startZ) ** 2 <= r ** 2) {
        await skills.placeBlock(bot, 'spruce_planks', x, startY + height + y, z);
      }
    }
  }
}

