const position = world.getPosition(bot);
const startX = position.x;
const startY = position.y;
const startZ = position.z;
const width = 20;
const depth = 20;
const height = 10;

// Foundation
for (let x = startX; x < startX + width; x++) {
    for (let z = startZ; z < startZ + depth; z++) {
        await skills.placeBlock(bot, 'stone', x, startY, z);
    }
}

// Walls
for (let y = startY + 1; y <= startY + height; y++) {
    for (let x = startX; x < startX + width; x++) {
        await skills.placeBlock(bot, 'stone_bricks', x, y, startZ);
        await skills.placeBlock(bot, 'stone_bricks', x, y, startZ + depth - 1);
    }
    for (let z = startZ; z < startZ + depth; z++) {
        await skills.placeBlock(bot, 'stone_bricks', startX, y, z);
        await skills.placeBlock(bot, 'stone_bricks', startX + width - 1, y, z);
    }
}

// Roof
const roofHeight = 5;
for (let r = 0; r < roofHeight; r++) {
    for (let x = startX - r; x < startX + width + r; x++) {
        for (let z = startZ - r; z < startZ + depth + r; z++) {
            await skills.placeBlock(bot, 'oak_stairs', x, startY + height + r, z);
        }
    }
}

// Windows and Doors
for (let y = startY + 2; y <= startY + height - 1; y += 3) {
    for (let x = startX + 1; x < startX + width - 1; x += 4) {
        await skills.placeBlock(bot, 'glass', x, y, startZ);
        await skills.placeBlock(bot, 'glass', x, y, startZ + depth - 1);
        await skills.placeBlock(bot, 'glass', x, y + 1, startZ);
        await skills.placeBlock(bot, 'glass', x, y + 1, startZ + depth - 1);
    }
    for (let z = startZ + 1; z < startZ + depth - 1; z += 4) {
        await skills.placeBlock(bot, 'glass', startX, y, z);
        await skills.placeBlock(bot, 'glass', startX + width - 1, y, z);
        await skills.placeBlock(bot, 'glass', startX, y + 1, z);
        await skills.placeBlock(bot, 'glass', startX + width - 1, y + 1, z);
    }
}

// Place some doors and torches
await skills.placeBlock(bot, 'oak_door', startX + (width / 2), startY + 1, startZ);
await skills.placeBlock(bot, 'oak_door', startX + (width / 2), startY + 2, startZ);

await skills.placeBlock(bot, 'torch', startX + 1, startY + 2, startZ + 1);
await skills.placeBlock(bot, 'torch', startX + width - 2, startY + 2, startZ + 1);
await skills.placeBlock(bot, 'torch', startX + 1, startY + 2, startZ + depth - 2);
await skills.placeBlock(bot, 'torch', startX + width - 2, startY + 2, startZ + depth - 2);

// Interior Walls for multiple rooms
for (let x = startX + 3; x < startX + width - 3; x += 5) {
    for (let y = startY + 1; y <= startY + height - 1; y++) {
        for (let z = startZ + 1; z < startZ + depth - 1; z++) {
            await skills.placeBlock(bot, 'stone_bricks', x, y, z);
        }
    }
}
for (let z = startZ + 3; z < startZ + depth - 3; z += 5) {
    for (let y = startY + 1; y <= startY + height - 1; y++) {
        for (let x = startX + 1; x < startX + width - 1; x++) {
            await skills.placeBlock(bot, 'stone_bricks', x, y, z);
        }
    }
}

log(bot,'Large mansion completed!');

