const position = world.getPosition(bot);

// Define farm size
const farmWidth = 9;
const farmHeight = 9;
const startX = position.x - Math.floor(farmWidth / 2);
const startZ = position.z - Math.floor(farmHeight / 2);

for (let x = startX; x < startX + farmWidth; x++) {
