for (let z = startZ; z < startZ + farmHeight; z++) {
    await skills.placeBlock(bot, 'oak_fence', startX - 1, position.y, z);
    await skills.placeBlock(bot, 'oak_fence', startX + farmWidth, position.y, z);
}

const radius = 5;
const towerHeight = 10;
const wallHeight = 7;

const buildTower = async (bot, centerX, centerZ) => {
    // Build a circular tower
    for (let y = 0; y < towerHeight; y++) {
        for (let dx = -radius; dx <= radius; dx++) {
            for (let dz = -radius; dz <= radius; dz++) {
                if (dx*dx + dz*dz <= radius*radius) {
                    await skills.placeBlock(bot, 'stone_bricks', centerX + dx, bot.entity.position.y + y, centerZ + dz);
                }
            }
        }
    }
};

const buildWall = async (bot, startX, startZ, endX, endZ) => {
    // Build walls between towers
    const lengthX = endX - startX;
    const lengthZ = endZ - startZ;
    for (let y = 0; y < wallHeight; y++) {
        for (let i = 0; i <= Math.max(Math.abs(lengthX), Math.abs(lengthZ)); i++) {
            const x = startX + (lengthX !== 0 ? i * Math.sign(lengthX) : 0);
            const z = startZ + (lengthZ !== 0 ? i * Math.sign(lengthZ) : 0);
            await skills.placeBlock(bot, 'stone_bricks', x, bot.entity.position.y + y, z);
        }
    }
};

const buildEmbrasures = async (bot, startX, startZ, endX, endZ) => {
    // Add embrasures to walls
    const lengthX = endX - startX;
    const lengthZ = endZ - startZ;
    for (let i = 0; i <= Math.max(Math.abs(lengthX), Math.abs(lengthZ)); i += 2) {
        const x = startX + (lengthX !== 0 ? i * Math.sign(lengthX) : 0);
        const z = startZ + (lengthZ !== 0 ? i * Math.sign(lengthZ) : 0);
        await skills.placeBlock(bot, 'air', x, bot.entity.position.y + 4, z);
    }
};

const buildCastle = async (bot) => {
    let position = world.getPosition(bot);
    const baseX = position.x;
    const baseZ = position.z;

    await buildTower(bot, baseX - 15, baseZ - 15);
    await buildTower(bot, baseX + 15, baseZ - 15);
