// Build the towers
async function buildTowers() {
  const towerPositions = [
    { x: pos.x, z: pos.z },
    { x: pos.x + castleWidth - 1, z: pos.z },
    { x: pos.x, z: pos.z + castleDepth - 1 },
    { x: pos.x + castleWidth - 1, z: pos.z + castleDepth - 1 }
  ];

  for (let tower of towerPositions) {
    for (let dx = -towerRadius; dx <= towerRadius; dx++) {
      for (let dz = -towerRadius; dz <= towerRadius; dz++) {
        for (let y = pos.y; y < pos.y + towerHeight; y++) {
          const distance = Math.sqrt(dx * dx + dz * dz);
          if (distance <= towerRadius) {
            await placeBlock("stone_bricks", tower.x + dx, y, tower.z + dz);
          }
        }
      }
    }
  }
}

